import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { SalesService } from 'src/app/services/sales.service';

@Component({
  selector: 'app-payment',
  templateUrl: './payment.component.html',
  styleUrls: ['./payment.component.css'],
})
export class PaymentComponent implements OnInit {
  orderData: any = {};
  isLoading = false;
  paymentSuccess = false;
  totalAmount = 0;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private salesService: SalesService,
  ) {}

  ngOnInit(): void {
    // Get order data from navigation state or localStorage
    const navigation = window.history.state;
    if (navigation.cartData) {
      this.orderData = navigation.cartData;
    } else {
      const savedCart = localStorage.getItem('checkout_cart');
      if (savedCart) {
        this.orderData = JSON.parse(savedCart);
      }
    }

    // Calculate total amount
    if (this.orderData.items) {
      this.totalAmount = this.orderData.items.reduce(
        (sum: number, item: any) => sum + item.price * item.quantity,
        0,
      );
    }
  }

  processPayment(): void {
    this.isLoading = true;

    const buyerName = localStorage.getItem('username');
    if (!buyerName) {
      alert('Please login first');
      this.router.navigate(['/login']);
      return;
    }

    // Create an order for each item in cart
    const orders = this.orderData.items?.map((item: any) => ({
      itemName: item.name,
      buyer: buyerName,
      price: item.price,
      quantity: item.quantity,
      delivered: false,
      orderStatus: 'PENDING',
      orderDate: new Date(),
      shippingAddress:
        localStorage.getItem('shippingAddress') || 'Not provided',
    }));

    if (!orders || orders.length === 0) {
      alert('No items in cart');
      this.router.navigate(['/cart']);
      return;
    }

    // Save each order to database
    const savePromises = orders.map((order: any) =>
      this.salesService.createOrder(order).toPromise(),
    );

    Promise.all(savePromises)
      .then(() => {
        this.isLoading = false;
        this.paymentSuccess = true;

        // Clear cart after successful payment
        localStorage.removeItem('checkout_cart');
        localStorage.removeItem('cart');

        setTimeout(() => {
          this.router.navigate(['/orders'], {
            queryParams: { payment: 'success' },
          });
        }, 2000);
      })
      .catch((err) => {
        this.isLoading = false;
        console.error('Error placing order:', err);
        alert('Failed to place order. Please try again.');
      });
  }

  // ✅ Add the missing skipPayment method
  skipPayment(): void {
    if (
      confirm(
        'Are you sure you want to skip payment? Your order will not be placed.',
      )
    ) {
      this.router.navigate(['/cart']);
    }
  }

  formatPrice(price: number): string {
    return price?.toLocaleString('en-IN') || '0';
  }
}
<div class="payment-card">
  <h2>Payment for {{ item.name }}</h2>
  <p><strong>Description:</strong> {{ item.description }}</p>
  <p><strong>Total:</strong> ₹{{ item.price }}</p>

  <div class="btn-group">
    <button class="btn btn-success" (click)="makePayment()">Pay Now</button>
    <button class="btn btn-secondary" (click)="skipPayment()">Skip</button>
  </div>
</div>

